import { Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // --- Geometry & Material -------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);

  const texture = ctx.textureLoader.load(config.assets?.imageUrl ?? '');
  const material = new MeshBasicNodeMaterial();
  // Node materials accept a texture via the map property
  material.map = texture;

  const mesh = new Mesh(geometry, material);

  // --- Placement -----------------------------------------------------------
  const pos = config.position ?? [0, 0, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // Store original Y for hover animation
  const originalY = mesh.position.y;

  // Keep track of GSAP timelines for cleanup
  const _timelines = [];

  // --- Interaction Handlers ------------------------------------------------
  const handlers = {
    hover: {
      /** @param {MouseEvent} _event */
      enter: () => {
        const tl = gsap.to(mesh.position, {
          y: originalY + 0.15,
          duration: 0.15,
          ease: 'power3.out',
        });
        _timelines.push(tl);
      },
      /** @param {MouseEvent} _event */
      leave: () => {
        const tl = gsap.to(mesh.position, {
          y: originalY,
          duration: 0.15,
          ease: 'power3.in',
        });
        _timelines.push(tl);
      },
    },
    click: () => {
      // press‑down animation
      const down = gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        onComplete: () => {
          const up = gsap.to(mesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.12,
            ease: 'back.out(1.7)',
          });
          _timelines.push(up);
        },
      });
      _timelines.push(down);

      // emit selection event if context provides an emitter
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-collection.select');
      }
    },
  };

  // --- UserData ------------------------------------------------------------
  mesh.userData.handlers = handlers;

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    _timelines.forEach((t) => t.kill && t.kill());
    _timelines.length = 0;
  };

  return mesh;
}
